from __future__ import annotations

from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # (employee, year) -> dict with "used" count
        self._usage: dict[tuple[str, int], int] = {}

    def _count_leave_days(self, start: date, end: date) -> int:
        total = 0
        day = start
        one = timedelta(days=1)
        while day <= end:
            if day.weekday() < 5 and day not in self.holidays:
                total += 1
            day += one
        return total

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("end date is before start date")
        if (start - today) < timedelta(days=3):
            raise ValueError("requests must be made at least 3 days in advance")

        days = self._count_leave_days(start, end)

        # Split across years if the request spans multiple years.
        # Charge each year's leave days against that year's allowance.
        year_total: dict[int, int] = {}
        day = start
        one = timedelta(days=1)
        while day <= end:
            if day.weekday() < 5 and day not in self.holidays:
                year_total[day.year] = year_total.get(day.year, 0) + 1
            day += one

        # Verify all years have enough remaining before committing.
        for y, needed in year_total.items():
            key = (employee, y)
            used = self._usage.get(key, 0)
            if used + needed > self.days_per_year:
                raise ValueError(
                    f"insufficient leave days for {employee} in {y}: "
                    f"requested {needed}, remaining {self.days_per_year - used}"
                )

        for y, needed in year_total.items():
            key = (employee, y)
            self._usage[key] = self._usage.get(key, 0) + needed

        return days

    def remaining(self, employee: str, year: int) -> int:
        used = self._usage.get((employee, year), 0)
        return max(0, self.days_per_year - used)
